    {addScope!==undefined&&<NewNodeModal scope={addScope?detail?.project.canvas.nodes.find(n=>n.id===addScope)?.title:undefined} onClose={()=>setAddScope(undefined)} onCreate={(kind,title,blockType,file)=>addNode(kind,addScope,title,blockType,file)}/>}
    {deleteCandidate&&<Modal title="Move project to Trash?" onClose={()=>setDeleteCandidate(null)}><p className="modal-description"><strong>{deleteCandidate.title}</strong> will leave your project list. Its notes, conversations and evidence stay on this computer and can be restored from Trash.</p><div className="modal-actions"><button className="secondary" onClick={()=>setDeleteCandidate(null)}>Keep project</button><button className="primary danger-primary" disabled={saving>0} onClick={()=>void trashProject(deleteCandidate)}><Trash2 size={15}/> Move to Trash</button></div></Modal>}
