function demoDisplayTitle(project:Project) {
  const names:Record<string,string>={
    'Demo · AI adoption in Dutch businesses · the banking question':'Dutch AI adoption',
    'Demo · When market conditions change · a historical risk baseline':'Historical market risk',
  };
  return project.canvas.nodes.some(node=>!node.parentId&&/^01[ ·]/.test(node.title)) ? names[project.title]||project.title : project.title;
}

function ProposalPreview({ proposal, revision, onClose, onAccept, onDismiss, onRefine, busy }: { proposal: Proposal; revision: number; onClose: () => void; onAccept: () => Promise<void>; onDismiss: () => Promise<void>; onRefine: () => void; busy: boolean }) {
  const stale = proposal.baseRevision !== revision;
  return <section className={`proposal-preview ${stale ? 'stale' : ''}`} aria-label="Proposal preview" data-testid="proposal-preview"><div className="row between"><span className="eyebrow"><GitBranch size={13} /> Canvas proposal</span><button className="icon-button" aria-label="Close proposal preview" onClick={onClose}><X size={15} /></button></div><h3>{proposal.summary}</h3><div className="proposal-operations">{proposal.operations.map((operation, index) => <span className={`operation-tag ${operation.type.startsWith('remove') ? 'remove' : operation.type.startsWith('add') ? 'add' : 'edit'}`} key={index}>{operation.type === 'addNode' ? `+ ${operation.node.title}` : operation.type === 'updateNode' ? `Edit ${operation.patch.title || 'node'}` : operation.type === 'removeNode' ? '− Remove node' : operation.type === 'addConnection' ? '+ Relationship' : '− Relationship'}</span>)}</div>{stale ? <p className="stale-warning">The canvas changed after this proposal. Ask for an updated preview before accepting.</p> : <p className="subtle">Highlighted changes follow your approval mode and shared research limits. Review the related Action before accepting.</p>}<div className="row gap"><button className="small primary" data-testid="accept-proposal" disabled={stale || busy} onClick={() => void onAccept()}><Check size={13} /> Accept changes</button><button className="small secondary" onClick={onRefine}>Refine</button><button className="small text-button" disabled={busy} data-testid="dismiss-proposal" onClick={() => void onDismiss()}>Dismiss</button></div></section>;
}

function Modal({ title, children, onClose, className = '', nonBlocking = false }: { title: string; children: ReactNode; onClose: () => void; className?: string; nonBlocking?: boolean }) {
  const panel = useRef<HTMLDivElement>(null);
  useEffect(() => { const previous = document.activeElement as HTMLElement | null; if (!panel.current?.contains(document.activeElement)) panel.current?.querySelector<HTMLElement>('[data-autofocus], input, select, textarea, button')?.focus(); return () => previous?.focus(); }, []);
  return <div className="modal-backdrop" onMouseDown={event => { if (event.target === event.currentTarget) onClose(); }}><div className={`modal ${className}`} role="dialog" aria-modal={!nonBlocking} aria-label={title} ref={panel} onKeyDown={event => { if (event.key !== 'Tab' || nonBlocking || event.defaultPrevented) return; const focusable = [...(panel.current?.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), textarea:not(:disabled), a[href]') || [])]; const first = focusable[0]; const last = focusable.at(-1); if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); } }}><div className="modal-heading"><h2>{title}</h2><button className="icon-button" aria-label="Close dialog" onClick={onClose}><X size={18} /></button></div>{children}</div></div>;
}
function NewProjectModal({ folders, onClose, onCreate, onOpenFolder, onDemo }: { folders: boolean; onDemo: () => void; onClose: () => void; onCreate: (title: string, start: 'blank'|'demo'|'conversation', question:string, folder?:string) => Promise<void>; onOpenFolder: (path:string) => Promise<boolean> }) {
  const [title,setTitle]=useState(''),[start,setStart]=useState<'blank'|'demo'|'conversation'|'folder'>('blank'),[question,setQuestion]=useState(''),[busy,setBusy]=useState(false);
  const suggestion=useFolderSuggestion(title,folders);
  const [folder,setFolder]=useState(''),[folderEdited,setFolderEdited]=useState(false),[existing,setExisting]=useState('');
  // The suggested folder follows the project name until the person types or picks their own.
  useEffect(()=>{if(suggestion&&!folderEdited)setFolder(suggestion.path);},[suggestion,folderEdited]);
  const needsFolder=Boolean(suggestion);
  const ready=start==='folder'?Boolean(existing.trim()):Boolean(title.trim())&&(start!=='conversation'||Boolean(question.trim()))&&(!needsFolder||Boolean(folder.trim()));
  const choices=[{id:'blank' as const,title:'Start blank',description:'An open canvas, ready for your notes.',icon:<Plus size={19}/>},{id:'demo' as const,title:'Explore a demo',description:'Build a guided example through four research stages.',icon:<BookOpen size={19}/>},{id:'conversation' as const,title:'Start a conversation',description:'Bring a question. Shape the research with ros.ai.',icon:<MessageSquare size={19}/>},...(needsFolder?[{id:'folder' as const,title:'Open a folder',description:'Use a folder you already have, or one ros.ai made before.',icon:<FolderOpen size={19}/>}]:[])];
  return <Modal title="Start a new project" className="new-project-modal" onClose={onClose}><p className="modal-description">Choose a starting point. Your canvas can grow in any direction.</p><form onSubmit={async event=>{event.preventDefault();if(busy||!ready)return;setBusy(true);try{if(start==='folder')await onOpenFolder(existing.trim());else await onCreate(title.trim(),start,question,needsFolder?folder.trim():undefined);}finally{setBusy(false);}}}><div className="project-start-choices" role="radiogroup" aria-label="Project starting point">{choices.map(choice=><button key={choice.id} type="button" role="radio" aria-checked={start===choice.id} className={start===choice.id?'selected':''} onClick={()=>choice.id==='demo'?onDemo():setStart(choice.id)}>{choice.icon}<span><strong>{choice.title}</strong><small>{choice.description}</small></span><span className="choice-radio">{start===choice.id&&<Check size={11}/>}</span></button>)}</div>
    {start==='folder'?<><label className="field-label" htmlFor="existing-folder">Folder</label><FolderField id="existing-folder" value={existing} picker={Boolean(suggestion?.picker)} placeholder="~/Documents/My research" onChange={path=>setExisting(path)}/><p className="folder-note">A folder ros.ai made opens with its canvas and history. Any other folder becomes a new project, and you choose which of its files to add.</p></>
    :<><label className="field-label" htmlFor="project-name">Project name</label><input id="project-name" data-testid="project-name" value={title} maxLength={200} onChange={event=>setTitle(event.target.value)} placeholder="What are you exploring?"/>
    {needsFolder&&<><label className="field-label" htmlFor="project-folder">Folder</label><FolderField id="project-folder" value={folder} picker={Boolean(suggestion?.picker)} onChange={(path,picked)=>{setFolder(path);setFolderEdited(true);if(picked&&!title.trim())setTitle(folderName(path));}}/><p className="folder-note">Notes, code and notebooks are saved here as ordinary files you can open in other apps. ros.ai creates the folder if needed.</p></>}</>}
    {start==='conversation'&&<><label className="field-label" htmlFor="initial-question">Your first question</label><textarea id="initial-question" rows={3} value={question} onChange={event=>setQuestion(event.target.value)} placeholder="What would you like to understand or investigate?"/><p className="subtle start-conversation-note">ros.ai can suggest a few connected notes after you discuss the question. Your project permissions apply.</p></>}{start==='demo'&&<p className="subtle start-conversation-note">The demo is a saved example, clearly labelled. Opening it does not run a model or an experiment.</p>}<div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancel</button><button type="submit" className="primary" data-testid="create-project" disabled={busy||!ready}>{busy?<LoaderCircle size={15} className="spin"/>:<ArrowRight size={15}/>} {start==='folder'?'Open folder':start==='conversation'?'Start conversation':start==='demo'?'Open demo':'Create project'}</button></div></form></Modal>;
}
function AttachModal({ detail, initial, onClose, onAttach }: { detail: ProjectDetail; initial: { artifact?: Artifact; nodeId?: string }; onClose: () => void; onAttach: (artifactId: string, nodeId: string, excerpt: string) => Promise<void> }) {
  const [artifactId, setArtifactId] = useState(initial.artifact?.id || ''); const [nodeId, setNodeId] = useState(initial.nodeId || ''); const [excerpt, setExcerpt] = useState(initial.artifact && initial.artifact.content !== detail.artifacts.find(a => a.id === initial.artifact?.id)?.content ? initial.artifact.content : ''); const [busy, setBusy] = useState(false);
  const artifact = detail.artifacts.find(a => a.id === artifactId); const available = detail.artifacts.filter(a => !initial.nodeId || a.nodeId !== initial.nodeId);
  const validExcerpt = !excerpt || Boolean(artifact?.content.includes(excerpt));
  return <Modal title="Attach a selected input" onClose={onClose}><p className="modal-description">Choose a saved version to share. Future results will not replace this selection or run the destination node.</p><form onSubmit={async event => { event.preventDefault(); if (!artifactId || !nodeId || busy || !validExcerpt) return; setBusy(true); await onAttach(artifactId, nodeId, excerpt); setBusy(false); }}><label className="field-label" htmlFor="attach-artifact">Saved result or source</label><select id="attach-artifact" value={artifactId} onChange={event => { setArtifactId(event.target.value); setExcerpt(''); }}><option value="">Choose an artifact…</option>{available.map(a => <option key={a.id} value={a.id}>{a.kind === 'source' ? 'Source' : 'Result'} · {a.title} · {date(a.createdAt)}</option>)}</select>{!available.length && <p className="subtle">Run research in another node to create a saved result.</p>}<label className="field-label" htmlFor="attach-node">Use in this node</label><select id="attach-node" value={nodeId} onChange={event => setNodeId(event.target.value)}><option value="">Choose a node…</option>{detail.project.canvas.nodes.filter(n => n.id !== artifact?.nodeId).map(n => <option key={n.id} value={n.id}>{n.title}</option>)}</select>{artifact && <><details className="attach-content"><summary>Inspect captured content</summary><pre>{artifact.content}</pre><span className="subtle">Source run {artifact.runId.slice(0, 8)} · version {artifact.hash.slice(0, 12)}</span></details><label className="field-label" htmlFor="attach-excerpt">Selected excerpt <span>optional</span></label><textarea id="attach-excerpt" value={excerpt} onChange={event => setExcerpt(event.target.value)} placeholder="Paste an exact passage, or leave empty to attach the whole artifact." rows={3} />{!validExcerpt && <p className="inline-error">The excerpt must match an exact passage in this saved artifact.</p>}</>}<div className="modal-actions"><button className="secondary" type="button" onClick={onClose}>Cancel</button><button className="primary" type="submit" disabled={!artifactId || !nodeId || busy || !validExcerpt}><ArrowRight size={14} /> Attach input</button></div></form></Modal>;
}

const blockChoices: {id:NodeKind|NewBlockType;kind:NodeKind;blockType?:NewBlockType;label:string;description:string;icon:typeof BookOpen}[] = [
  {id:'topic',kind:'topic',label:'Knowledge',description:'What you study',icon:BookOpen},
  {id:'activity',kind:'activity',label:'Action',description:'What you do',icon:Play},
  {id:'group',kind:'group',label:'Group',description:'A frame for mixed research blocks',icon:Group},
  {id:'dataset',kind:'topic',blockType:'dataset',label:'Dataset',description:'Import and inspect a CSV',icon:Database},
  {id:'code',kind:'topic',blockType:'code',label:'Code',description:'Write and run an isolated program',icon:Braces},
  {id:'notebook',kind:'topic',blockType:'notebook',label:'Notebook',description:'Run Python cell by cell, or open a .ipynb',icon:NotebookPen},
  {id:'report',kind:'topic',blockType:'report',label:'Report',description:'Write with exact saved evidence',icon:FileText},
];

function NewNodeModal({scope,onClose,onCreate}: {scope?:string;onClose:()=>void;onCreate:(kind:NodeKind,title:string,blockType?:NewBlockType,notebookFile?:File)=>Promise<void>}) {
  const [choiceId,setChoiceId]=useState<NodeKind|NewBlockType>('topic');
  const [notebookFile,setNotebookFile]=useState<File|null>(null);
  const [title,setTitle]=useState('');
  const [busy,setBusy]=useState(false);
  const choice=blockChoices.find(value=>value.id===choiceId)!;
  return <Modal title={scope?`Add inside ${scope}`:'Add to project canvas'} onClose={onClose}>
    <form onSubmit={async event=>{
      event.preventDefault();
      if(busy)return;
      setBusy(true);
      try{await onCreate(choice.kind,title.trim(),choice.blockType,choice.blockType==='notebook'?notebookFile??undefined:undefined);}finally{setBusy(false);}
    }}>
      <div className="kind-choices" role="group" aria-label="Block type">
        {blockChoices.map(({id,label,description,icon:Icon})=><button key={id} type="button" className={choiceId===id?'selected':''} aria-pressed={choiceId===id} disabled={busy} onClick={()=>setChoiceId(id)}>
          <strong><Icon size={18}/>{label}</strong><span>{description}</span>
        </button>)}
      </div>
      <label className="field-label" htmlFor="new-node-title">Name <span>(optional)</span></label>
      <input id="new-node-title" value={title} onChange={event=>setTitle(event.target.value)} maxLength={200} placeholder={choice.blockType==='notebook'&&notebookFile?notebookFile.name.replace(/\.ipynb$/iu,''):choice.label} disabled={busy}/>
      {choice.blockType==='notebook'&&<><label className="field-label" htmlFor="new-notebook-file">Start from a Jupyter notebook <span>(optional .ipynb)</span></label><input id="new-notebook-file" type="file" accept=".ipynb,application/x-ipynb+json" disabled={busy} onChange={event=>setNotebookFile(event.target.files?.[0]??null)}/></>}
      <p className="subtle node-kind-note">{choice.blockType==='code'?'Adds it to the canvas and opens the editor so you can start writing.':choice.blockType==='notebook'?notebookFile?'Opens a copy of this notebook in ros.ai. Nothing runs until you run a cell.':'Adds it to the canvas and opens an empty notebook, ready for Python.':'Add it to the canvas now. Open the block when you’re ready to work on it.'}</p>
      <div className="modal-actions"><button type="button" className="secondary" onClick={onClose} disabled={busy}>Cancel</button><button className="primary" disabled={busy}>{busy?'Adding…':choice.blockType==='code'?'Add & write code':choice.blockType==='notebook'?'Add & open notebook':`Add ${choice.label}`}</button></div>
    </form>
  </Modal>;
}
